import sys
import os
import time
import json
import requests

CACHE_FILE = 'cache.bin'
CACHE_EXPIRY = 60

def fetch_json(url):
    response = requests.get(url)
    response.raise_for_status()
    return response.json()

def load_cache():
    with open(CACHE_FILE, 'r') as f:
        return json.load(f)

def save_cache(data):
    with open(CACHE_FILE, 'w') as f:
        json.dump(data, f)

def main(url):
    use_cache = False
    if os.path.exists(CACHE_FILE):
        cache_mtime = os.path.getmtime(CACHE_FILE)
        if time.time() - cache_mtime < CACHE_EXPIRY:
            use_cache = True

    if use_cache:
        data = load_cache()
    else:
        data = fetch_json(url)
        save_cache(data)

    print(data['status'])

if __name__ == '__main__':
    if len(sys.argv) != 2:
        print('Usage: python fetch_cache.py <URL>')
        sys.exit(1)
    main(sys.argv[1])
